using System.Text.Json;

namespace NanoCAD.McpServer;

internal static class ModelParameterSchema
{
    public static JsonElement Input() => JsonDocument.Parse("""
    {"type":"object","additionalProperties":false,
      "description":"Change one actual supported native control or a document User driver through its current owner, expression and dependency graph. Exactly one of value or expression. Supported typed controls include active Dist first/second extrusion lengths; exact first extrusion taper, active Different second taper and sweep taper whose owning degree scalar agrees with the native radians getter; inward default Shell thickness with an observed exact driver ID (read/literal editing only; named-variable formulas are unavailable); existing TwoEdges/TwoVertices hole placement length offsets and the first radial distance when their exact owning IDs are available; verified native degree revolution Angle; fillet Radius and chamfer first/second distances; thread pitch and finite length; rectangular pattern counts/steps; circular pattern count and verified degree angular step; retained native offset-plane scalar; and explicitly scoped numeric placement components. A readable ID, variable name or generic angular flag does not establish its owning control or units. Count controls require positive integers; each native owner validates its exact value domain. value accepts a finite scalar in the verified owning control's actual units and value domain and requires the target's current stored numeric literal; it never silently replaces a formula. expression uses finite numbers, exact existing names, parentheses and + - * / only, with no functions, implicit units or commands. Use expression for intentional formula changes or arithmetic. Document User scalars remain within +/-1e12 native units. Angles and parameter_changes value_unit follow the verified actual binding; count, linear, degree and User units are distinct. propagate=true explicitly admits native downstream variable cascades. scope_handles explicitly includes every affected/referenced body in the same owning network; foreign or unknown consumers remain protected. Native feature identities, stored formulas, profile/source links, intentional suppression choices and actual affected dependency closure remain checked while derived geometry can rebuild. Exact owned internal sketch linear/radius/diameter drivers can bind arithmetic to named User variables through their actual relation VarID and owner-MCS host. Read owner_kind/sketch_id/constraint_id/control_kind from get_model_variables, then exact sketch/constraint metadata; identity observation alone is not edit eligibility. The linked planner applies affected sketches and rebuilds scoped consumers. Literal reference-only measurements, projection-owned controls, unverified angular mappings, Hole diameter/depth/seat drivers without an exact public binding, the unverified radial placement angle, unsupported Shell direction/per-face controls and arbitrary internal variables remain outside this adapter. Missing optional Hole/Shell bindings are reported without disabling other readable controls; an observed ID alone does not establish edit eligibility. set_sketch_constraint_parameter remains the literal-only relation editor; use expression here for an intentional formula change. Placement formulas with variable references remain protected after an observed native persistence failure; explicitly scoped numeric components retain their actual pivot/order and peer components. Read current variables/history, use returned body_ref and inspect the meaningful resulting geometry and affected drawings after the connected change. Native rebuild feasibility and retained expression readback decide the result; no separate comparison model is required. Recovery and Undo are not guaranteed; unknown is neither success nor rollback.",
     "required":["bridge_instance_id","document_id","expected_revision","operation_id","units","handle","variable_id","expected_expression"],
     "oneOf":[{"required":["value"],"not":{"required":["expression"]}},{"required":["expression"],"not":{"required":["value"]}}],
     "properties":{
       "bridge_instance_id":{"type":"string","format":"uuid"},"document_id":{"type":"string","format":"uuid"},
       "operation_id":{"type":"string","format":"uuid"},"expected_revision":{"type":"string","pattern":"^[0-9]{1,20}$"},
       "units":{"const":"Millimeters"},"handle":{"type":"string","pattern":"^[0-9A-Fa-f]{1,16}$"},
       "variable_id":{"type":"string","pattern":"^\\{[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}\\}$"},
       "expected_expression":{"type":"string","minLength":1,"description":"Exact currently stored native expression from get_model_variables. Limited by the actual request frame, not the new-expression grammar."},
       "value":{"type":"number","description":"Finite scalar in the exact verified owning control's units and value domain; counts require positive integers. Current target expression must be a numeric literal. Native owner validation occurs before writing."},
       "expression":{"type":"string","minLength":1,"maxLength":1024,"description":"New arithmetic over exact variable names from get_model_variables:128 tokens, nesting16. Use for explicit formula replacement, signed/zero literals and other supported native controls. Stored downstream expressions are observed completely with byte/cancellation budgets. Exact native owner/units and planned consumers are checked before writing; cycles or unknown consumers are refused."},
       "scope_handles":{"type":"array","minItems":1,"uniqueItems":true,"items":{"type":"string","pattern":"^[0-9A-Fa-f]{1,16}$"},"description":"Optional explicit selected body scope including handle, in one actual owning MCS network. Every affected or referenced native feature consumer must belong to this scope; it does not admit arbitrary readable variables or foreign consumers. Enables scoped controls and retained numeric AssocMove/AssocRotate components with the existing pivot, peer components and native order preserved. Placement expressions must contain no variable references because their persistence was not retained by an earlier native rebuild. Other supported feature formulas use the actual planned native graph. Counts are integral; each bound native owner validates the requested value and actual units. Intentional healthy suppression remains a retained state. Refresh body/history/affected drawings after rebuild. Recovery and Undo are not guaranteed."},
       "propagate":{"type":"boolean","default":false,"description":"Set true to intentionally change existing downstream variables through the supported actual native owning controls and document User scalar graph. All affected/referenced consumers must be in the selected body or explicit scope_handles; it does not admit unknown ownership or arbitrary native variable families. value with propagate=true also uses this linked planner and still protects a formula-driven target from silent replacement."}
     }}
    """).RootElement.Clone();
}
